std::vector<PolygonWithHoles2d> result;
if (P1.isEmpty() || P2.isEmpty()) {
    return result;
}
try {
    CGAL::Polygon_2<CGAL::Epick> p1_cgal, p2_cgal;
    for (const auto& pt : P1.outerBoundary()) {
        p1_cgal.push_back(CGAL::Point_2<CGAL::Epick>(pt.x, pt.y));
    }
    for (const auto& pt : P2.outerBoundary()) {
        p2_cgal.push_back(CGAL::Point_2<CGAL::Epick>(pt.x, pt.y));
    }
    std::list<CGAL::Polygon_with_holes_2<CGAL::Epick>> intersection;
    CGAL::intersection(p1_cgal, p2_cgal, std::back_inserter(intersection));
    for (const auto& poly_with_holes : intersection) {
        PolygonWithHoles2d result_poly;
        std::vector<Point2d> outer;
        for (auto it = poly_with_holes.outer_boundary().vertices_begin(); it != poly_with_holes.outer_boundary().vertices_end(); ++it) {
            outer.emplace_back(it->x(), it->y());
        }
        result_poly.setOuterBoundary(outer);
        for (auto it = poly_with_holes.holes_begin(); it != poly_with_holes.holes_end(); ++it) {
            std::vector<Point2d> hole;
            for (auto hit = it->vertices_begin(); hit != it->vertices_end(); ++hit) {
                hole.emplace_back(hit->x(), hit->y());
            }
            result_poly.addHole(hole);
        }
        result.push_back(result_poly);
    }
} catch (...) {
    // Handle any CGAL or geometric errors gracefully
}
return result;

